BEGIN;

-- 1. Add updated_at column
ALTER TABLE naf_codes ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();

-- 2. Drop old validation column, add boolean valide column
ALTER TABLE naf_codes DROP COLUMN IF EXISTS validation;
ALTER TABLE naf_codes ADD COLUMN IF NOT EXISTS valide BOOLEAN NOT NULL DEFAULT false;

-- 3. RLS write policy for super_admin/admin
ALTER TABLE naf_codes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "naf_codes_admin_write" ON naf_codes;
CREATE POLICY "naf_codes_admin_write" ON naf_codes
  FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM users_profile
      WHERE users_profile.id = auth.uid()
      AND users_profile.role IN ('super_admin', 'admin')
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM users_profile
      WHERE users_profile.id = auth.uid()
      AND users_profile.role IN ('super_admin', 'admin')
    )
  );

-- Allow read access for all authenticated users
DROP POLICY IF EXISTS "naf_codes_read" ON naf_codes;
CREATE POLICY "naf_codes_read" ON naf_codes
  FOR SELECT
  USING (auth.role() = 'authenticated');

